require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/auth.php';$u=require_role(['ADMIN']);$vnp=private_config('vnpay');$integrations=private_config('integrations');
handle_form(function()use($u,$vnp,$integrations){throttle('settings-password',(string)$u['id'],6,900);$pw=$_POST['confirm_password']??'';must(is_string($pw)&&password_verify($pw,$u['password']),'Nhập lại mật khẩu quản trị để lưu cấu hình.');$kind=post('kind');must($kind==='vnpay'||setting('external_auth'),'Chức năng xác thực ngoài đã tắt.');if($kind==='vnpay'){$c=$vnp;$c['tmn_code']=valid_text(post('tmn_code'),50);if(post('hash_secret')!=='')$c['hash_secret']=post('hash_secret');must(!empty($c['hash_secret']),'Cần HashSecret do VNPay cung cấp.');$ret=post('return_url');must(filter_var($ret,FILTER_VALIDATE_URL)&&(str_starts_with($ret,'https://')||str_starts_with($ret,'http://localhost/')),'Return URL phải là địa chỉ HTTPS (hoặc localhost để phát triển).');$c['return_url']=$ret;$c['payment_url']='https://sandbox.vnpayment.vn/paymentv2/vpcpay.html';private_save('vnpay',$c);}
else{$allowed=['smtp'=>['host','port','username','password','from','secure'],'twilio'=>['sid','token','from'],'google'=>['client_id','client_secret','redirect_uri'],'facebook'=>['client_id','client_secret','redirect_uri']];must(isset($allowed[$kind]),'Loại cấu hình không hợp lệ.');$c=$integrations[$kind]??[];foreach($allowed[$kind]as$key){$value=post($key);if(in_array($key,['password','token','client_secret'],true)&&$value==='')continue;$c[$key]=$value;}if(in_array($kind,['google','facebook'],true))must(filter_var($c['redirect_uri'],FILTER_VALIDATE_URL)&&str_starts_with($c['redirect_uri'],'https://'),'OAuth redirect URI cần HTTPS.');if($kind==='smtp'){must(filter_var($c['from'],FILTER_VALIDATE_EMAIL),'Email gửi không hợp lệ.');must(in_array($c['secure'],['tls','ssl'],true),'Chọn TLS hoặc SSL.');must(ctype_digit($c['port'])&&(int)$c['port']>0&&(int)$c['port']<=65535,'Cổng SMTP không hợp lệ.');}$integrations[$kind]=$c;private_save('integrations',$integrations);}
audit('CAU_HINH_TICH_HOP','settings',$kind,null,['da_luu'=>true]);
},'admin/cau_hinh_he_thong.php');
page_start('Cấu hình tích hợp','Khóa được lưu ngoài thư mục website. Ô khóa để trống sẽ giữ nguyên giá trị đang có.');echo '<div class="panel"><h2>VNPay Sandbox</h2>';notice(!empty($vnp['hash_secret'])?'Đã có thông tin merchant. Cần kiểm tra IPN và Return URL bằng sandbox.':'Chưa có khóa merchant; các phần khác của website vẫn sử dụng được.');token_form();field('kind','','vnpay','hidden');field('tmn_code','TmnCode',$vnp['tmn_code']??'','text','required');field('hash_secret','HashSecret mới','','password','autocomplete="new-password"');field('return_url','Return URL',$vnp['return_url']??'','url','required');field('confirm_password','Mật khẩu quản trị hiện tại','','password','required autocomplete="current-password"');echo '<button>Lưu VNPay</button></form><p class="muted">Đăng ký IPN tại VNPay: URL công khai của ứng dụng + /thanh_toan/vnpay_ipn.php. Return URL kết thúc bằng /thanh_toan/vnpay_return.php. Localhost không nhận được IPN từ máy chủ VNPay.</p></div>';
if(setting('external_auth'))foreach(['smtp'=>'Email OTP (SMTP)','twilio'=>'SMS OTP (Twilio)','google'=>'Đăng nhập Google','facebook'=>'Đăng nhập Facebook']as$kind=>$label){echo '<details><summary>'.e($label).'</summary>';token_form();field('kind','',$kind,'hidden');$keys=['smtp'=>['host'=>'Máy chủ SMTP','port'=>'Cổng (587 TLS / 465 SSL)','username'=>'Tài khoản SMTP','password'=>'Mật khẩu SMTP mới','from'=>'Email người gửi','secure'=>'Bảo mật: tls hoặc ssl'],'twilio'=>['sid'=>'Account SID','token'=>'Auth Token mới','from'=>'Số gửi Twilio'],'google'=>['client_id'=>'Client ID','client_secret'=>'Client Secret mới','redirect_uri'=>'Redirect URI kết thúc xac_thuc/google_callback.php'],'facebook'=>['client_id'=>'App ID','client_secret'=>'App Secret mới','redirect_uri'=>'Redirect URI kết thúc xac_thuc/facebook_callback.php']][$kind];foreach($keys as$k=>$text){$secret=in_array($k,['password','token','client_secret'],true);field($k,$text,$secret?'':($integrations[$kind][$k]??''),$secret?'password':'text');}field('confirm_password','Mật khẩu quản trị hiện tại','','password','required');echo '<button>Lưu cấu hình</button></form></details>';}
